   {
   const size_t output_size = 2*m_p_words + 2;
   std::vector<word> ws(output_size);
   BigInt z(BigInt::Positive, output_size);
   bigint_sqr(z.mutable_data(), z.size(), x.data(), x.size(), x.sig_words(), ws.data(), ws.size());
   bigint_monty_redc(z.mutable_data(), m_p.data(), m_p_words, m_p_dash, ws.data(), ws.size());
   ...
   }
```

So `z` has `output_size = 2*m_p_words + 2` words. And `bigint_monty_redc` needs `z_size = 2*(p_size+1) = 2*p_size + 2`. These match.

